<?php require_once '../includes/config.php'; require_role('admin'); $title='Customers'; $rows=db()->query("SELECT id,name,email,status,created_at FROM users WHERE role='customer' ORDER BY id DESC")->fetchAll(); require '../includes/header.php'; ?><h1 class="section-title">Customers</h1><div class="bg-white border rounded-4 overflow-hidden"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Name</th><th>Email</th><th>Status</th><th>Joined</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= e($r['email']) ?></td><td><?= $r['status']?'Active':'Inactive' ?></td><td><?= e($r['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php require '../includes/footer.php'; ?>
